-- THE MODERN DAY BIBLE BY NATHAN TABOR
-- Recovery archive; user-supplied text unmodified. Missing stories not fabricated.
-- 100 numbered source entries (#102–201) + 52 separate kinship index rows + seven recalled aisle names.
-- SOURCE MATERIAL NOT INDEPENDENTLY KJV VERIFIED
BEGIN TRANSACTION;
CREATE TABLE modern_bible_stories(entry_id TEXT PRIMARY KEY, source_sequence INTEGER NOT NULL UNIQUE, title_as_supplied TEXT NOT NULL,bible_reference_as_supplied TEXT NOT NULL,description_as_supplied TEXT NOT NULL,verbatim_entry_line TEXT NOT NULL,source_section_as_supplied TEXT NOT NULL,source_text_status TEXT NOT NULL);
CREATE TABLE biblical_kinship_52(id TEXT PRIMARY KEY,source_sequence INTEGER,title_as_supplied TEXT,bible_reference_as_supplied TEXT,section_as_supplied TEXT,validation TEXT);
CREATE TABLE original_aisles_as_reported(aisle_no INTEGER PRIMARY KEY,label TEXT NOT NULL,provenance TEXT NOT NULL);
CREATE TABLE recovery_metadata(key TEXT PRIMARY KEY,value TEXT NOT NULL);
COMMIT;
